parameters.jsCode:
const input = $json;

let chatId, messageId, username, firstName, lastName, isPremium, languageCode, callbackData, query, offset;

if (input.body && input.body.callback_query) {
  const callback = input.body.callback_query;
  const message = callback.message;
  chatId = message.chat.id;
  messageId = message.message_id;
  const from = callback.from;
  username = from.username || null;
  firstName = from.first_name || '';
  lastName = from.last_name || '';
  isPremium = from.is_premium || false;
  languageCode = from.language_code || 'en';
  callbackData = callback.data || '';
} else if (input.callback_query) {
  const callback = input.callback_query;
  const message = callback.message;
  chatId = message.chat.id;
  messageId = message.message_id;
  const from = callback.from;
  username = from.username || null;
  firstName = from.first_name || '';
  lastName = from.last_name || '';
  isPremium = from.is_premium || false;
  languageCode = from.language_code || 'en';
  callbackData = callback.data || '';
} else if (input.chat_id) {

  chatId = input.chat_id;
  messageId = input.message_id || null;
  username = input.username || null;
  firstName = input.first_name || '';
  lastName = input.last_name || '';
  isPremium = input.is_premium || false;
  languageCode = input.language_code || 'en';
  callbackData = input.callback_data || '';
} else {
  throw new Error('Cannot extract callback data from input');
}

const parts = callbackData.split('|');
const action = parts[0];
const parsedQuery = parts[1] || '';
const offsetRaw = parts[2] || '0';
const parsedOffset = parseInt(offsetRaw, 10);

if (action !== 'more') {
  throw new Error('Invalid callback data for more_results');
}

return [{
  json: {
    chat_id: chatId,
    message_id: messageId,
    username: username,
    first_name: firstName,
    last_name: lastName,
    is_premium: isPremium,
    language_code: languageCode,
    callback_data: callbackData,
    query: parsedQuery,
    offset: parsedOffset
  }
}];

