parameters.jsCode:
const files = $input.all().map(item => item.json);
const aggregateData = $('Agregate data').first().json;

const chatId = aggregateData.chat_id;
const replyToMessageId = aggregateData.message_id;
const query = aggregateData.query;
const offset = Number(aggregateData.offset || 0);
const pageSize = 8;

const validFiles = files.filter(file => file && file.id);
const filesPage = validFiles.slice(0, pageSize);

let inline_keyboard = [];
let text = '';

if (validFiles.length === 0) {
  text = '🔍 No more tracks found.\n\n✨ Upgrade to Pro Mode for unlimited access to all tracks!\n\n@PocketSound_bot';

  inline_keyboard = [
    [
      {
        text: '🎵 Sound Search',
        callback_data: '/soundsearch'
      }
    ],
    [
      {
        text: '💎 Activate Pro Mode',
        callback_data: '/pro_mode'
      }
    ]
  ];
} else {

  inline_keyboard = filesPage.map(file => ([
    {
      text: `${file.title} — ${file.artist}`,
      callback_data: `get|${file.id}`
    }
  ]));

  if (validFiles.length === pageSize) {
    inline_keyboard.push([
      {
        text: 'More…',
        callback_data: `more|${query}|${offset + pageSize}`
      }
    ]);
  }

  inline_keyboard.push([
    {
      text: '🎵 New Search',
      callback_data: '/soundsearch'
    }
  ]);

  if (validFiles.length < pageSize && offset > 0) {
    text = '🎵 End of search results.\n\n@PocketSound_bot';
  } else {
    text = `🔎 Search results for: "${query}"\n\nSelect a track:\n\n@PocketSound_bot`;
  }
}

return [{
  json: {
    chat_id: chatId,
    reply_to_message_id: replyToMessageId,
    text: text,
    reply_markup: { inline_keyboard }
  }
}];

const parsedData = $('Parse more callback').first().json;
const userData = $('Check User in DB').first().json;

return [{
  json: {

    chat_id: parsedData.chat_id,
    message_id: parsedData.message_id,
    username: parsedData.username,
    first_name: parsedData.first_name,
    last_name: parsedData.last_name,
    is_premium: parsedData.is_premium,
    language_code: parsedData.language_code,
    callback_data: parsedData.callback_data,
    query: parsedData.query,
    offset: parsedData.offset,

    user_id: userData.id,
    user_tg_id: userData.tg_id,
    is_banned: userData.is_banned,
    admin_active: userData.admin_active,
    support_topic_id: userData.support_topic_id,

    page_size: 8,
    next_offset: parsedData.offset + 8
  }
}];

